class_name VcgTinyMotionGame
extends RefCounted

signal changed(snapshot: Dictionary)

const MOTION_API_SCHEMA_VERSION := "0.4.0"
const CORE_PROFILE := "body.core17"
const OBSTACLE_PROFILE := "actions.obstacle.v1"
const CORE_LANDMARKS := [
	"nose",
	"left_eye",
	"right_eye",
	"left_ear",
	"right_ear",
	"left_shoulder",
	"right_shoulder",
	"left_elbow",
	"right_elbow",
	"left_wrist",
	"right_wrist",
	"left_hip",
	"right_hip",
	"left_knee",
	"right_knee",
	"left_ankle",
	"right_ankle",
]
const CONTROLLER_ACTIONS := ["left", "right", "jump", "duck"]
const OBSTACLE_ACTIONS := ["dodge_left", "dodge_right", "jump", "duck"]

var snapshot := {
	"lane": 1,
	"stance": "standing",
	"score": 0,
	"motion_ready": false,
	"input_source": "waiting",
	"status": "WAITING FOR PLAYER",
}


func current_snapshot() -> Dictionary:
	return snapshot.duplicate(true)


func accept_health(value: Variant) -> bool:
	if typeof(value) != TYPE_DICTIONARY:
		return false
	var health: Dictionary = value
	if health.get("schemaVersion") != MOTION_API_SCHEMA_VERSION:
		return false
	var status_value: Variant = health.get("status", "")
	var availability_value: Variant = health.get("controlAvailability", "")
	var reason_value: Variant = health.get("reason", "")
	if typeof(status_value) != TYPE_STRING or typeof(availability_value) != TYPE_STRING or typeof(reason_value) != TYPE_STRING:
		return false
	var status: String = status_value
	var availability: String = availability_value
	var reason: String = reason_value
	var ready: bool = status == "ready" and availability == "full"
	snapshot["motion_ready"] = ready
	snapshot["input_source"] = snapshot["input_source"] if ready else "waiting"
	snapshot["status"] = "MOTION READY" if ready else "MOTION %s" % reason.replace("-", " ").to_upper()
	_publish()
	return true


func accept_frame(value: Variant) -> bool:
	if typeof(value) != TYPE_DICTIONARY:
		return false
	var frame: Dictionary = value
	if frame.get("schemaVersion") != MOTION_API_SCHEMA_VERSION:
		return false
	if typeof(frame.get("sequence")) != TYPE_INT or typeof(frame.get("sourceTimestampMs")) not in [TYPE_INT, TYPE_FLOAT]:
		return false
	var capabilities_value: Variant = frame.get("capabilities")
	var players_value: Variant = frame.get("players")
	if typeof(capabilities_value) != TYPE_DICTIONARY or typeof(players_value) != TYPE_ARRAY:
		return false
	var profiles_value: Variant = capabilities_value.get("profiles")
	if typeof(profiles_value) != TYPE_ARRAY or not CORE_PROFILE in profiles_value:
		return false
	var players: Array = players_value
	if frame.get("health") != "ready" or players.is_empty():
		snapshot["motion_ready"] = false
		snapshot["input_source"] = "waiting"
		snapshot["status"] = "MOTION DEGRADED" if not players.is_empty() else "PLAYER NOT FOUND"
		_publish()
		return true
	if typeof(players[0]) != TYPE_DICTIONARY:
		return false
	var player: Dictionary = players[0]
	var landmarks := _validated_landmarks(player.get("coreLandmarks"))
	if landmarks.is_empty():
		return false
	var actions_value: Variant = player.get("actions")
	if typeof(actions_value) != TYPE_ARRAY:
		return false

	var hip_center: float = (landmarks["left_hip"].x + landmarks["right_hip"].x) / 2.0
	snapshot["lane"] = 0 if hip_center < 0.44 else (2 if hip_center > 0.56 else 1)
	snapshot["motion_ready"] = true
	snapshot["input_source"] = "motion"
	snapshot["status"] = "LANDMARKS ACTIVE"

	for action_value in actions_value:
		if typeof(action_value) != TYPE_DICTIONARY:
			return false
		var action: Dictionary = action_value
		var action_name: Variant = action.get("name")
		var phase: Variant = action.get("phase")
		if typeof(action_name) != TYPE_STRING or typeof(phase) != TYPE_STRING:
			return false
		if action_name in OBSTACLE_ACTIONS and not OBSTACLE_PROFILE in profiles_value:
			return false
		if phase != "triggered":
			continue
		if action_name == "dodge_left":
			_apply("left", "motion")
		elif action_name == "dodge_right":
			_apply("right", "motion")
		elif action_name == "jump":
			_apply("jump", "motion")
		elif action_name == "duck":
			_apply("duck", "motion")
	_publish()
	return true


func accept_controller(action: String) -> bool:
	if action not in CONTROLLER_ACTIONS:
		return false
	_apply(action, "controller")
	_publish()
	return true


func _validated_landmarks(value: Variant) -> Dictionary:
	if typeof(value) != TYPE_ARRAY:
		return {}
	var result := {}
	for landmark_value in value:
		if typeof(landmark_value) != TYPE_DICTIONARY:
			return {}
		var landmark: Dictionary = landmark_value
		var name: Variant = landmark.get("name")
		var position_value: Variant = landmark.get("position")
		if typeof(name) != TYPE_STRING or name not in CORE_LANDMARKS or result.has(name):
			return {}
		if typeof(position_value) != TYPE_DICTIONARY:
			return {}
		var x: Variant = position_value.get("x")
		var y: Variant = position_value.get("y")
		if typeof(x) not in [TYPE_INT, TYPE_FLOAT] or typeof(y) not in [TYPE_INT, TYPE_FLOAT]:
			return {}
		if not is_finite(float(x)) or not is_finite(float(y)) or x < 0 or x > 1 or y < 0 or y > 1:
			return {}
		result[name] = Vector2(float(x), float(y))
	return result if result.size() == CORE_LANDMARKS.size() else {}


func _apply(action: String, source: String) -> void:
	if action == "left":
		snapshot["lane"] = maxi(0, int(snapshot["lane"]) - 1)
	elif action == "right":
		snapshot["lane"] = mini(2, int(snapshot["lane"]) + 1)
	snapshot["stance"] = "jumping" if action == "jump" else ("ducking" if action == "duck" else "standing")
	snapshot["score"] = int(snapshot["score"]) + 100
	snapshot["input_source"] = source
	snapshot["status"] = "%s %s" % [source.to_upper(), action.to_upper()]


func _publish() -> void:
	changed.emit(current_snapshot())

class_name VcgMotionReplay
extends RefCounted

var _game: RefCounted
var _frames: Array
var _cursor := 0
var _position_ms := 0.0
var _first_timestamp_ms := 0.0
var _playing := false


func _init(game: RefCounted, trace: Dictionary) -> void:
	_game = game
	if trace.get("format") != "vcg-motion-trace" or trace.get("formatVersion") != 1:
		return
	if trace.get("containsRawFrames") != false or typeof(trace.get("frames")) != TYPE_ARRAY:
		return
	var candidate_frames: Array = trace["frames"]
	if candidate_frames.is_empty():
		return
	var prior_timestamp := -INF
	for frame_value in candidate_frames:
		if typeof(frame_value) != TYPE_DICTIONARY:
			return
		var timestamp: Variant = frame_value.get("sourceTimestampMs")
		if typeof(timestamp) not in [TYPE_INT, TYPE_FLOAT] or not is_finite(float(timestamp)):
			return
		if float(timestamp) < prior_timestamp:
			return
		prior_timestamp = float(timestamp)
	_frames = candidate_frames.duplicate(true)
	_first_timestamp_ms = float(_frames[0]["sourceTimestampMs"])


func is_valid() -> bool:
	return not _frames.is_empty()


func play() -> bool:
	if not is_valid():
		return false
	_playing = true
	return true


func advance(elapsed_ms: float) -> int:
	if not _playing or not is_finite(elapsed_ms) or elapsed_ms < 0:
		return 0
	_position_ms += elapsed_ms
	var emitted := 0
	while _cursor < _frames.size():
		var relative_time := float(_frames[_cursor]["sourceTimestampMs"]) - _first_timestamp_ms
		if relative_time > _position_ms:
			break
		if not _game.accept_frame(_frames[_cursor]):
			_playing = false
			return emitted
		_cursor += 1
		emitted += 1
	if _cursor == _frames.size():
		_playing = false
	return emitted


func reset() -> void:
	_cursor = 0
	_position_ms = 0.0
	_playing = false

class_name VcgMotionWebBridge
extends RefCounted

const PROTOCOL_VERSION := 2
const MOTION_API_SCHEMA_VERSION := "0.4.0"
const ORIGIN_PATTERN := "^https?://[A-Za-z0-9.-]+(?::[0-9]{1,5})?$"
const MAX_SAFE_INTEGER := 9_007_199_254_740_991.0

var _game: RefCounted
var _target_origin: String
var _client_id: String
var _helper: JavaScriptObject
var _message_callback: JavaScriptObject
var _session_id := ""


func _init(game: RefCounted, target_origin: String, client_id := "vcg-godot-tiny-game") -> void:
	_game = game
	_target_origin = target_origin
	_client_id = client_id


func start() -> bool:
	if not OS.has_feature("web") or not _valid_origin(_target_origin):
		return false
	JavaScriptBridge.eval("""
		window.__vcgGodotMotionBridge = {
			listener: null,
			start(origin, clientId, callback) {
				this.stop();
				this.listener = (event) => {
					if (event.origin === origin && event.source === window.parent) {
						callback(JSON.stringify(event.data));
					}
				};
				window.addEventListener("message", this.listener);
				window.parent.postMessage({
					type: "vcg.motion.hello",
					protocolVersion: 2,
					motionApiSchemaVersion: "0.4.0",
					clientId,
					request: {
						requiredProfiles: ["body.core17"],
						optionalProfiles: ["actions.obstacle.v1"]
					}
				}, origin);
			},
			ack(origin, sessionId, sequence) {
				window.parent.postMessage({
					type: "vcg.motion.ack",
					protocolVersion: 2,
					sessionId,
					sequence
				}, origin);
			},
			goodbye(origin, sessionId) {
				window.parent.postMessage({
					type: "vcg.motion.goodbye",
					protocolVersion: 2,
					sessionId
				}, origin);
			},
			stop() {
				if (this.listener) window.removeEventListener("message", this.listener);
				this.listener = null;
			}
		};
	""")
	_helper = JavaScriptBridge.get_interface("__vcgGodotMotionBridge")
	if _helper == null:
		return false
	_message_callback = JavaScriptBridge.create_callback(_on_message)
	_helper.start(_target_origin, _client_id, _message_callback)
	return true


func stop() -> void:
	if _helper != null:
		if not _session_id.is_empty():
			_helper.goodbye(_target_origin, _session_id)
		_helper.stop()
	_session_id = ""
	_message_callback = null
	_helper = null


func _on_message(arguments: Array) -> void:
	if arguments.is_empty() or typeof(arguments[0]) != TYPE_STRING:
		return
	var parsed: Variant = JSON.parse_string(arguments[0])
	if typeof(parsed) != TYPE_DICTIONARY:
		return
	var message: Dictionary = parsed
	if message.get("protocolVersion") != PROTOCOL_VERSION:
		return
	var message_type: Variant = message.get("type")
	if message_type == "vcg.motion.welcome":
		if message.get("motionApiSchemaVersion") != MOTION_API_SCHEMA_VERSION:
			return
		var negotiation: Variant = message.get("negotiation")
		var health: Variant = message.get("health")
		var session_id: Variant = message.get("sessionId")
		if typeof(negotiation) != TYPE_DICTIONARY or negotiation.get("accepted") != true:
			return
		if typeof(session_id) != TYPE_STRING or session_id.is_empty() or not _game.accept_health(health):
			return
		_session_id = session_id
	elif message_type == "vcg.motion.health":
		if message.get("sessionId") == _session_id:
			_game.accept_health(message.get("event"))
	elif message_type == "vcg.motion.frame":
		if message.get("sessionId") != _session_id or typeof(message.get("frame")) != TYPE_DICTIONARY:
			return
		var frame: Dictionary = message["frame"]
		var sequence_value: Variant = frame.get("sequence")
		if not valid_json_sequence(sequence_value):
			return
		var sequence := int(sequence_value)
		frame["sequence"] = sequence
		if _game.accept_frame(frame):
			_helper.ack(_target_origin, _session_id, sequence)


static func valid_json_sequence(value: Variant) -> bool:
	if typeof(value) not in [TYPE_INT, TYPE_FLOAT]:
		return false
	var numeric := float(value)
	return is_finite(numeric) and numeric >= 0.0 and numeric <= MAX_SAFE_INTEGER and floor(numeric) == numeric


func _valid_origin(value: String) -> bool:
	var expression := RegEx.new()
	return expression.compile(ORIGIN_PATTERN) == OK and expression.search(value) != null

examples/godot-motion-game/tests/run_tes.text:
extends SceneTree

const TinyGame := preload("res://scripts/motion_game.gd")
const MotionReplay := preload("res://scripts/motion_replay.gd")
const WebBridge := preload("res://scripts/motion_web_bridge.gd")

var _failures: Array[String] = []


func _init() -> void:
	call_deferred("_run")


func _run() -> void:
	_test_landmarks_actions_and_fallback()
	_test_replay_is_deterministic_and_raw_free()
	_test_bridge_denies_non_web_and_unsafe_origins()
	_test_bridge_normalizes_json_sequences()
	if _failures.is_empty():
		print("Godot Motion sample: 4 tests passed")
		quit(0)
	else:
		for failure in _failures:
			push_error(failure)
		quit(1)


func _test_landmarks_actions_and_fallback() -> void:
	var game := TinyGame.new()
	_expect(game.accept_frame(_frame(0, 1000, 0.3)), "portable frame should validate")
	_expect(game.current_snapshot()["lane"] == 0, "hip landmarks should select left lane")
	var triggered := _frame(1, 1100, 0.5, [{"name": "jump", "phase": "triggered"}])
	_expect(game.accept_frame(triggered), "triggered obstacle frame should validate")
	_expect(game.current_snapshot()["stance"] == "jumping", "triggered jump should change stance")
	var held := _frame(2, 1200, 0.5, [{"name": "duck", "phase": "held"}])
	_expect(game.accept_frame(held), "held feedback frame should validate")
	_expect(game.current_snapshot()["stance"] == "jumping", "held feedback must not trigger duck")
	var shell := _frame(3, 1300, 0.5, [{"name": "menu_back", "phase": "triggered"}])
	shell["capabilities"]["profiles"].append("actions.shell.v1")
	_expect(game.accept_frame(shell), "shell action frame should remain valid")
	_expect(game.current_snapshot()["stance"] == "jumping", "shell actions must not drive gameplay")
	_expect(game.accept_controller("right"), "controller fallback should remain available")
	_expect(game.current_snapshot()["input_source"] == "controller", "controller should own the recovery input")


func _test_replay_is_deterministic_and_raw_free() -> void:
	var trace := {
		"format": "vcg-motion-trace",
		"formatVersion": 1,
		"containsRawFrames": false,
		"frames": [_frame(0, 1000, 0.5), _frame(1, 1100, 0.7, [{"name": "duck", "phase": "triggered"}])],
	}
	var first_game := TinyGame.new()
	var first := MotionReplay.new(first_game, trace)
	_expect(first.is_valid() and first.play(), "skeleton-only replay should initialize")
	_expect(first.advance(0) == 1 and first.advance(100) == 1, "replay should follow the controlled clock")
	var second_game := TinyGame.new()
	var second := MotionReplay.new(second_game, trace)
	second.play()
	second.advance(100)
	_expect(first_game.current_snapshot() == second_game.current_snapshot(), "replay must be deterministic")
	var raw_trace := trace.duplicate(true)
	raw_trace["containsRawFrames"] = true
	_expect(not MotionReplay.new(TinyGame.new(), raw_trace).is_valid(), "raw-frame trace must be rejected")


func _test_bridge_denies_non_web_and_unsafe_origins() -> void:
	var game := TinyGame.new()
	var unsafe := WebBridge.new(game, "https://console.example/path")
	_expect(not unsafe.start(), "path-bearing origin must be rejected")
	var headless := WebBridge.new(game, "https://console.example")
	_expect(not headless.start(), "non-web runtime must not claim a live web bridge")


func _test_bridge_normalizes_json_sequences() -> void:
	_expect(WebBridge.valid_json_sequence(0.0), "integral JSON sequence should be accepted")
	_expect(WebBridge.valid_json_sequence(9_007_199_254_740_991.0), "maximum safe JSON sequence should be accepted")
	_expect(not WebBridge.valid_json_sequence(-1.0), "negative JSON sequence must be rejected")
	_expect(not WebBridge.valid_json_sequence(0.5), "fractional JSON sequence must be rejected")
	_expect(not WebBridge.valid_json_sequence(INF), "non-finite JSON sequence must be rejected")
	_expect(not WebBridge.valid_json_sequence("1"), "string JSON sequence must be rejected")


func _frame(sequence: int, timestamp_ms: int, hip_x: float, actions: Array = []) -> Dictionary:
	var landmarks := []
	for name in TinyGame.CORE_LANDMARKS:
		var x := hip_x if name in ["left_hip", "right_hip"] else 0.5
		landmarks.append({"name": name, "position": {"x": x, "y": 0.5}})
	return {
		"schemaVersion": "0.4.0",
		"sequence": sequence,
		"source": "replay",
		"sourceTimestampMs": timestamp_ms,
		"health": "ready",
		"capabilities": {
			"profiles": ["body.core17", "actions.obstacle.v1"],
		},
		"players": [{
			"id": "player-1",
			"coreLandmarks": landmarks,
			"actions": actions,
		}],
	}


func _expect(condition: bool, message: String) -> void:
	if not condition:
		_failures.append(message)

