  for (const [key, digest] of Object.entries(value.provenance)) {
    if (key.endsWith("Sha256")) assert.match(digest, SHA256_PATTERN);
  }
  assert.equal(
    value.claimBoundary,
    GODOT_WEB_BRIDGE_RESILIENCE_CLAIM_BOUNDARY,
  );
  assert.deepEqual(
    value.limitations,
    GODOT_WEB_BRIDGE_RESILIENCE_LIMITATIONS,
